import { DeviceInfo } from '../device-info';
import { DeviceType } from '../device-info/device-type';
import { IOrientationState, OrientationValue } from './types';

export class OrientationStateBuilder {
    private mIsInverted?: boolean;
    public get isInverted(): boolean {
        return this.mIsInverted ?? false;
    }
    private set isInverted(value: boolean) {
        this.mIsInverted = value;
    }

    public constructor(private deviceType: DeviceType, private deviceInfo: DeviceInfo, private ignoreInversion: boolean = false, private forcedOrientation: OrientationValue | undefined = undefined) {}

    private getOrientationAngle() {
        if (window.screen.orientation !== undefined) {
            return Math.abs(window.screen.orientation.angle);
        }
        // deprecated in favour of screen.orientation, included for old browsers
        if (window.orientation !== undefined) {
            return Math.abs(window.orientation as number);
        }

        //simple aspect ratio comparator
        return window.innerWidth > window.innerHeight ? 90 : 0;
    }

    private getOrientation(): OrientationValue {
        if (this.forcedOrientation) { return this.forcedOrientation; }
        if (this.deviceType.isDesktop) {
            return 'landscape';
        }

        const angle = this.getOrientationAngle();
        const calculatedValue = this.getCalculatedValue();
        const isAtAngle = angle % 180 !== 0;
        const isNotAtAngle = !isAtAngle;
        let value: OrientationValue = isAtAngle ? 'landscape' : 'portrait';

        if (this.mIsInverted === undefined) {
            this.isInverted = (isAtAngle && calculatedValue !== 'landscape') || (isNotAtAngle && calculatedValue !== 'portrait');
        }

        if (this.isInverted && !this.ignoreInversion) {
            value = value === 'portrait' ? 'landscape' : 'portrait';
        }

        // Old school iOS hack to make sure we dont get any toolbars at the bottom of the browser window
        if (this.deviceInfo.browser.is('Safari')) {
            window.scrollTo(0, 0);
        }

        return value;
    }

    public build(isChanging: boolean = false): IOrientationState {
        const orientation = this.getOrientation();

        return {
            value: orientation,
            isLandscape: orientation === 'landscape',
            isPortrait: orientation === 'portrait',
            isInverted: this.isInverted ?? false,
            isChanging
        };
    }

    public getCalculatedValue(): OrientationValue {
        if (this.deviceType.isAndroidNative) {
            return window.screen.width > window.screen.height ? 'landscape' : 'portrait';
        }

        if (this.deviceType.isTablet && this.deviceType.isIosNative) {
            return window.screen.width > window.innerHeight ? 'landscape' : 'portrait';
        }

        return window.innerWidth > window.innerHeight ? 'landscape' : 'portrait';
    }
}
